head.script:
scwin.getErrorLog = function() {
	var temp = WebSquare.logger.getErrorLog();
	return temp;
};

// WESD-35: 클릭 전 group(tagname="a") 표시 → setSrc 로 새로 그려졌는지 확인
scwin.markOld = function() {
	document.getElementById($p.id + "wframe1_group1").setAttribute("data-old", "1");
};

scwin.checkReloaded = function() {
	var g = document.getElementById($p.id + "wframe1_group1");
	return !!g && !g.hasAttribute("data-old");
};
